      this.indicator = this.shadowRoot.querySelector(".indicator");
      this.details = this.shadowRoot.querySelector(".details");
      this.button = this.shadowRoot.querySelector(".expand");

      this.header.addEventListener("click", () => this.toggle());
      this.header.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          this.toggle();
        }
      });
      this.button.addEventListener("click", () => this.toggle());
    }

    toggle() {
      this.expanded = !this.expanded;
      this.details.hidden = !this.expanded;
      this.indicator.textContent = this.expanded ? "−" : "+";
      this.header.setAttribute("aria-expanded", String(this.expanded));
      this.button.textContent = this.expanded ? "collapse" : "expand more";
    }
  }

  customElements.define("x-details", XDetails);
